const readButton = document.getElementById('read-values');
const log = document.getElementById('log');

readButton.addEventListener('nys-click', () => {
  const name = document.getElementById('name-field').value;
  const email = document.getElementById('email-field').value;
  const phone = document.getElementById('phone-field').value;
  const comments = document.getElementById('comments-field').value;
  log.textContent = `Name: ${name || '(empty)'} | Email: ${email || '(empty)'} | Phone: ${phone || '(empty)'} | Comments: ${comments || '(empty)'}`;
});
